
-- BUSINESS QUESTION 21:
-- What is the lifetime revenue generated by each customer?

WITH customer_orders AS (
    SELECT
        c.customer_unique_id,
        o.order_id,
        o.order_purchase_timestamp,
        SUM(oi.price) AS order_value
    FROM public.customers c
    INNER JOIN public.orders o
        ON c.customer_id = o.customer_id
    INNER JOIN public.order_items oi
        ON o.order_id = oi.order_id
    GROUP BY
        c.customer_unique_id,
        o.order_id,
        o.order_purchase_timestamp
)
SELECT
    customer_unique_id,
    COUNT(order_id) AS total_orders,
    ROUND(SUM(order_value)::NUMERIC, 2) AS lifetime_revenue,
    MIN(order_purchase_timestamp) AS first_purchase,
    MAX(order_purchase_timestamp) AS last_purchase
FROM customer_orders
GROUP BY customer_unique_id
ORDER BY lifetime_revenue DESC
LIMIT 20;


-- BUSINESS QUESTION 22:
-- How many customers are repeat customers?

WITH customer_order_counts AS (
    SELECT
        c.customer_unique_id,
        COUNT(DISTINCT o.order_id) AS total_orders
    FROM public.customers c
    INNER JOIN public.orders o
        ON c.customer_id = o.customer_id
    GROUP BY c.customer_unique_id
)
SELECT
    COUNT(*) AS total_customers,
    COUNT(*) FILTER (
        WHERE total_orders > 1
    ) AS repeat_customers,
    COUNT(*) FILTER (
        WHERE total_orders = 1
    ) AS one_time_customers,
    ROUND(
        COUNT(*) FILTER (WHERE total_orders > 1) * 100.0 /
        NULLIF(COUNT(*), 0),
        2
    ) AS repeat_customer_percentage
FROM customer_order_counts;


-- BUSINESS QUESTION 23:
-- How frequently do customers purchase from the business?

WITH customer_order_counts AS (
    SELECT
        c.customer_unique_id,
        COUNT(DISTINCT o.order_id) AS total_orders
    FROM public.customers c
    INNER JOIN public.orders o
        ON c.customer_id = o.customer_id
    GROUP BY c.customer_unique_id
)
SELECT
    total_orders,
    COUNT(*) AS number_of_customers,
    ROUND(
        COUNT(*) * 100.0 /
        SUM(COUNT(*)) OVER (),
        2
    ) AS customer_percentage
FROM customer_order_counts
GROUP BY total_orders
ORDER BY total_orders;


-- BUSINESS QUESTION 24:
-- What is the average number of days between customer purchases?

WITH customer_order_dates AS (
    SELECT
        c.customer_unique_id,
        o.order_id,
        o.order_purchase_timestamp,
        LAG(o.order_purchase_timestamp) OVER (
            PARTITION BY c.customer_unique_id
            ORDER BY o.order_purchase_timestamp
        ) AS previous_purchase
    FROM public.customers c
    INNER JOIN public.orders o
        ON c.customer_id = o.customer_id
),
purchase_intervals AS (
    SELECT
        customer_unique_id,
        EXTRACT(
            EPOCH FROM (
                order_purchase_timestamp - previous_purchase
            )
        ) / 86400.0 AS days_between_orders
    FROM customer_order_dates
    WHERE previous_purchase IS NOT NULL
)
SELECT
    COUNT(*) AS repeat_purchase_intervals,
    ROUND(AVG(days_between_orders)::NUMERIC, 2)
        AS average_days_between_purchases
FROM purchase_intervals;


-- BUSINESS QUESTION 25:
-- Which orders experienced the longest delivery delays?

SELECT
    order_id,
    order_status,
    order_purchase_timestamp,
    order_estimated_delivery_date,
    order_delivered_customer_date,
    ROUND(
        (
            EXTRACT(
                EPOCH FROM (
                    order_delivered_customer_date -
                    order_estimated_delivery_date
                )
            ) / 86400.0
        )::NUMERIC,
        2
    ) AS delivery_delay_days
FROM public.orders
WHERE order_status = 'delivered'
  AND order_delivered_customer_date IS NOT NULL
  AND order_estimated_delivery_date IS NOT NULL
  AND order_delivered_customer_date >
      order_estimated_delivery_date
ORDER BY delivery_delay_days DESC
LIMIT 20;


-- BUSINESS QUESTION 26:
-- What percentage of delivered orders arrived on time?

WITH delivery_performance AS (
    SELECT
        order_id,
        CASE
            WHEN order_delivered_customer_date <=
                 order_estimated_delivery_date
            THEN 'On Time'
            WHEN order_delivered_customer_date >
                 order_estimated_delivery_date
            THEN 'Delayed'
            ELSE 'Unknown'
        END AS delivery_status
    FROM public.orders
    WHERE order_status = 'delivered'
      AND order_delivered_customer_date IS NOT NULL
      AND order_estimated_delivery_date IS NOT NULL
)
SELECT
    delivery_status,
    COUNT(*) AS total_orders,
    ROUND(
        COUNT(*) * 100.0 /
        SUM(COUNT(*)) OVER (),
        2
    ) AS percentage_of_delivered_orders
FROM delivery_performance
GROUP BY delivery_status
ORDER BY total_orders DESC;


-- BUSINESS QUESTION 27:
-- Which sellers generate the highest revenue?

SELECT
    s.seller_id,
    s.seller_city,
    s.seller_state,
    COUNT(DISTINCT oi.order_id) AS total_orders,
    COUNT(*) AS total_items_sold,
    ROUND(SUM(oi.price)::NUMERIC, 2) AS total_revenue,
    ROUND(AVG(oi.price)::NUMERIC, 2) AS average_item_price
FROM public.sellers s
INNER JOIN public.order_items oi
    ON s.seller_id = oi.seller_id
GROUP BY
    s.seller_id,
    s.seller_city,
    s.seller_state
ORDER BY total_revenue DESC
LIMIT 20;


-- BUSINESS QUESTION 28:
-- Which states have the highest customer satisfaction?

WITH order_review_scores AS (
    SELECT
        order_id,
        AVG(review_score) AS average_order_review
    FROM public.order_reviews
    GROUP BY order_id
)
SELECT
    c.customer_state,
    COUNT(*) AS reviewed_orders,
    ROUND(
        AVG(r.average_order_review)::NUMERIC,
        2
    ) AS average_review_score,
    COUNT(*) FILTER (
        WHERE r.average_order_review >= 4
    ) AS positive_review_orders
FROM order_review_scores r
INNER JOIN public.orders o
    ON r.order_id = o.order_id
INNER JOIN public.customers c
    ON o.customer_id = c.customer_id
GROUP BY c.customer_state
ORDER BY average_review_score DESC;


-- BUSINESS QUESTION 29:
-- How can customers be segmented by lifetime spending?

WITH customer_revenue AS (
    SELECT
        c.customer_unique_id,
        SUM(oi.price) AS lifetime_revenue
    FROM public.customers c
    INNER JOIN public.orders o
        ON c.customer_id = o.customer_id
    INNER JOIN public.order_items oi
        ON o.order_id = oi.order_id
    GROUP BY c.customer_unique_id
),
customer_segments AS (
    SELECT
        customer_unique_id,
        lifetime_revenue,
        CASE
            WHEN lifetime_revenue >= 1000 THEN 'High Value'
            WHEN lifetime_revenue >= 500 THEN 'Medium Value'
            ELSE 'Low Value'
        END AS customer_segment
    FROM customer_revenue
)
SELECT
    customer_segment,
    COUNT(*) AS total_customers,
    ROUND(
        SUM(lifetime_revenue)::NUMERIC,
        2
    ) AS segment_revenue,
    ROUND(
        AVG(lifetime_revenue)::NUMERIC,
        2
    ) AS average_customer_spending
FROM customer_segments
GROUP BY customer_segment
ORDER BY segment_revenue DESC;


-- BUSINESS QUESTION 30:
-- How do customer review scores relate to delivery performance?

WITH delivery_data AS (
    SELECT
        order_id,
        CASE
            WHEN order_delivered_customer_date <=
                 order_estimated_delivery_date
            THEN 'On Time'
            WHEN order_delivered_customer_date >
                 order_estimated_delivery_date
            THEN 'Delayed'
        END AS delivery_status
    FROM public.orders
    WHERE order_status = 'delivered'
      AND order_delivered_customer_date IS NOT NULL
      AND order_estimated_delivery_date IS NOT NULL
),
review_data AS (
    SELECT
        order_id,
        AVG(review_score) AS average_review_score
    FROM public.order_reviews
    GROUP BY order_id
)
SELECT
    d.delivery_status,
    COUNT(*) AS reviewed_orders,
    ROUND(
        AVG(r.average_review_score)::NUMERIC,
        2
    ) AS average_review_score
FROM delivery_data d
INNER JOIN review_data r
    ON d.order_id = r.order_id
GROUP BY d.delivery_status
ORDER BY average_review_score DESC;


